t500: # packed results chained back to back (each waits for the one before)
    li   a0, 500
    li   t0, 0xf0f0f0f0f0f0f0f0
    li   t1, 0x2020202020202020
    paddus.b t2, t0, t1
    psubus.b t3, t2, t1
    psad.b a3, t3, t0
